import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import GameCard from '../components/pages/GameCard';
import './StorePage.css';

const StorePage = () => {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [games, setGames] = useState([]);
  const [ownedGames, setOwnedGames] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    loadGames();
    if (user) {
      loadOwnedGames();
    }
  }, [user]);

  const loadGames = async () => {
    try {
      const response = await api.get('/games');
      setGames(response.data);
    } catch (error) {
      console.error('Ошибка загрузки игр:', error);
    } finally {
      setLoading(false);
    }
  };

  const loadOwnedGames = async () => {
    try {
      const response = await api.get('/users/profile/games');
      setOwnedGames(response.data);
    } catch (error) {
      console.error('Ошибка загрузки библиотеки:', error);
    }
  };

  const addToCart = async (gameId) => {
    try {
      await api.post(`/cart/add/${gameId}`);
      alert('✅ Добавлено в корзину');
    } catch (error) {
      alert(error.response?.data?.message || 'Ошибка добавления');
    }
  };

  const cartTotal = ownedGames.reduce((sum, item) => sum + item.price, 0);

  const filteredGames = games.filter(game => {
    const matchesFilter = filter === 'all' || game.genre === filter;
    const matchesSearch = game.title.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesFilter && matchesSearch;
  });

  const genres = ['all', ...new Set(games.map(g => g.genre))];

  if (loading) {
    return (
      <div className="store-page">
        <div className="loading">Загрузка игр...</div>
      </div>
    );
  }

  return (
    <div className="store-page">
      <div className="store-header">
        <h1>🛒 Магазин игр</h1>
        {user && (
          <div className="user-balance">
            💰 Баланс: <strong>{user.balance?.toFixed(2) || 0} ₽</strong>
            <button onClick={() => navigate('/topup')} className="btn-topup-small">
              Пополнить
            </button>
          </div>
        )}
      </div>

      <div className="store-controls">
        <input
          type="text"
          placeholder="🔍 Поиск игр..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          className="search-input"
        />
        
        <div className="genre-filters">
          {genres.map(genre => (
            <button
              key={genre}
              className={`genre-btn ${filter === genre ? 'active' : ''}`}
              onClick={() => setFilter(genre)}
            >
              {genre === 'all' ? 'Все' : genre}
            </button>
          ))}
        </div>
      </div>

      <div className="store-content">
        <div className="games-grid">
          {filteredGames.map(game => {
            const isOwned = ownedGames.some(og => og.id === game.id);
            
            return (
              <GameCard 
                key={game.id} 
                game={game} 
                owned={isOwned}
              />
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default StorePage;
